/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        scwin.vSECT_CHG_TP_CD = dts_Item.getCellData(1, "SECT_CHG_TP_CD");
        if (edt_CHG_DD.getValue() > vCurDate) {
            buttonSet.setUpdateStatus();

            /*
            btn_Revwr.src = "../img/btn_study.gif";
            	btn_Revwr.disabled = false;

            	btn_Approve.src = "../img/btn_approval.gif";
            	btn_Approve.disabled = false;

            	if (getObjectValue(edt_REVW_DDTM) != "") {
            		btn_Revwr.src = "../img/btn_study_d.gif";
            		btn_Revwr.disabled = true;
            	}

            	if (getObjectValue(edt_APPROV_DDTM) != "") {
            		btn_Approve.src = "../img/btn_approval_d.gif";
            		btn_Approve.disabled = true;
            	}
             */

            // 090720-팀원은 컴토만, 팀장은 승인만

            if (js_jobtitl === "03") {
                // 팀원'03'

                btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                btn_Revwr.setDisabled(false);
                btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                btn_Approve.setDisabled(true);
                if (edt_REVW_DDTM.getValue() !== "") {
                    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                    btn_Revwr.setDisabled(true);
                }
                if (edt_APPROV_DDTM.getValue() !== "") {
                    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                    btn_Approve.setDisabled(true);
                }
            } else {
                // 팀장 외

                btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                btn_Revwr.setDisabled(true);
                btn_Approve.setBackgroundImage("../img/btn_approval.gif");
                btn_Approve.setDisabled(false);
                if (edt_REVW_DDTM.getValue() !== "") {
                    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                    btn_Revwr.setDisabled(true);
                }
                if (edt_APPROV_DDTM.getValue() !== "") {
                    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                    btn_Approve.setDisabled(true);
                }
            }
            // 승인이 되면 수정,삭제버튼 비활성화
            if (edt_APPROV_DDTM.getValue() !== "") {
                buttonSet.setErrorStatus(); // disable 시킨다.
                btn_lineadd.src = "../img/btn_fileadd_dis.gif";
                btn_lineadd.setDisabled(true);
                btn_linedelete.src = "../img/btn_filedelete_dis.gif";
                btn_linedelete.setDisabled(true);
            }
        } else {
            buttonSet.setErrorStatus(); // disable 시킨다.
            btn_lineadd.src = "../img/btn_fileadd_dis.gif";
            btn_lineadd.setDisabled(true);
            btn_linedelete.src = "../img/btn_filedelete_dis.gif";
            btn_linedelete.setDisabled(true);
            if (edt_REVW_DDTM.getValue() !== "") {
                btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                btn_Revwr.setDisabled(true);
            }
            if (edt_APPROV_DDTM.getValue() !== "") {
                btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                btn_Approve.setDisabled(true);
            }
        }
        if (scwin.vAcptNo !== "") {
            // 컨버젼하기가 어려워 제외됨..
            btn_lineadd.src = "../img/btn_fileadd_dis.gif";
            btn_lineadd.setDisabled(true);
            btn_linedelete.src = "../img/btn_filedelete_dis.gif";
            btn_linedelete.setDisabled(true);
        }
        if (edt_CHG_DD.getValue() !== "") {
            // 인쇄버튼 활성화
            btn_Print.setBackgroundImage("../img/btn_print.gif");
            btn_Print.setDisabled(false);
        } else {
            // 인쇄버튼 비활성화
            btn_Print.setBackgroundImage("../img/btn_print_d.gif");
            btn_Print.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05235.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05235.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05235.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Log_OnFail
 * @description Log On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Log_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.TR_JOB));
        await $c.win.alert(trs_Log);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05235.trs_Log_OnFail" });
    }
};

/**
 * @method
 * @name trs_Log_OnSuccess
 * @description Log On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Log_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.TR_JOB));
        scwin.parentRefresh();
        await scwin.readSync();

        // 검토시 신주인수권증권 있는지 확인
        if (scwin.pLogType === "1") {
            await scwin.popopSW();
            if (dts_sw.getCellData(1, "CNT") > 0) {
                await $c.win.alert("신주인수권증권있습니다. 소속부변경 시장조치를 해주십시오.");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05235.trs_Log_OnSuccess" });
    }
};

