/**
 * @method
 * @name grd_ATTACH_FILE_OnDblClick
 * @description grd_ATTACH_FILE 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ATTACH_FILE_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_File.getRowStatus(dts_File.getRowPosition()) === 0) {
            $c.elw.fn_filedown(dts_File);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05235.grd_ATTACH_FILE_OnDblClick" });
    }
};

