 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_File.removeRow(dts_File.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05235.btn_linedelete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
     */
    const arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }, {
        cid: "SECT_INVSTG_TP_CD",
        cnm: "cmb_AFCHG_SECT_INVSTG_TP_CD"
    }, {
        cid: "SECT_CHG_RSN_CD",
        cnm: "cmb_SECT_CHG_RSN"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                if (arrCid[i].cid === "01362") {
                    if (dts_Cod.getCellData(j, "VALUE") === "10") {
                        strCbd = strCbd + "^-----------------------------------------------------";
                    }
                }
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name extrReadSync
 * @description extr Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.extrReadSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    await scwin.fileReadSync();
};

/**
 * @method
 * @name fileReadSync
 * @description file Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileReadSync = async function() {
    if (scwin.vAcptNo !== "") {
        // 컨버젼하기가 어려워 제외됨..
        const sbmOptions = {
            id : "sbm_dts_File",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_File=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        const sbmOptions = {
            id : "sbm_dts_File",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_File=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
