        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (edt_APPROV_DDTM.getValue() !== "") {
        await $c.win.alert("승인처리가 완료된 후 삭제 할 수 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';
    if (scwin.vSECT_CHG_TP_CD === 'N') {
        await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 삭제 할 수 없습니다.");
        cmb_SECT_CHG_TP_CD.focus();
        return;
        // 심사팀에서 신규상장시 입력한 자료라서 삭제 불가(신규상장한건도 삭제처리됨.).
    }
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TR_JOB_DELETE);
};

/**
 * @method
 * @name revwr
 * @description revwr 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revwr = async function() {
    scwin.TR_JOB = '검토처리';
    scwin.pLogType = "1";
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        await scwin.trslog('1');
    }
};

/**
 * @method
 * @name approve
 * @description approve 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approve = async function() {
    if (edt_REVW_DDTM.getValue() === "") {
        await $c.win.alert("검토처리가 완료된 후 승인처리를 할 수 있습니다.");
        return;
    }
    scwin.TR_JOB = '승인처리';
    scwin.pLogType = "2";
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        await scwin.trslog('2');
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_Search;
    fr_fn_list_sync();
};

/**
 * @method
 * @name filedown
 * @description filedown 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(dtsObj) {
    const vKey = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    const attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (scwin.vAcptNo !== "") {
        location.href = "/filedownload.do?file_id=" + vKey + "&attach_seq=" + attach_seq + "&gubun=12";
    } else {
        location.href = "/filedownload.do?file_id=" + vKey + "&attach_seq=" + attach_seq + "&gubun=23";
    }
};
